using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;
using ChurnPredictor;

var builder = WebApplication.CreateBuilder(args);

// Train the model at startup and register prediction pool
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

var data = mlContext.Data.LoadFromTextFile<ChurnInput>(dataPath, hasHeader: true, separatorChar: ',');
var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

// Map "Yes"/"No" → true/false using ValueMappingEstimator (serializable)
var labelKeys = new[] { "Yes", "No" };
var labelValues = new[] { true, false };

var pipeline = mlContext.Transforms.Conversion.MapValue("Label", labelKeys, labelValues, nameof(ChurnInput.Churned))
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnInput.Region)))
    .Append(mlContext.Transforms.NormalizeMeanVariance("AgeNorm", nameof(ChurnInput.Age)))
    .Append(mlContext.Transforms.NormalizeMeanVariance("IncomeNorm", nameof(ChurnInput.Income)))
    .Append(mlContext.Transforms.NormalizeMeanVariance("PurchaseNorm", nameof(ChurnInput.PurchaseHistory)))
    .Append(mlContext.Transforms.Concatenate("Features", "AgeNorm", "IncomeNorm", "RegionEncoded", "PurchaseNorm"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());

var model = pipeline.Fit(split.TrainSet);

// Evaluate on test set
var predictions = model.Transform(split.TestSet);
try
{
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}
catch (ArgumentOutOfRangeException)
{
    Console.WriteLine("Model trained — test set too small for full evaluation metrics. Add more data for reliable metrics.");
}

// Save model and register prediction pool
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
mlContext.Model.Save(model, split.TrainSet.Schema, modelPath);

builder.Services.AddPredictionEnginePool<ChurnInput, ChurnOutput>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST to /predict");

app.MapPost("/predict", (PredictionEnginePool<ChurnInput, ChurnOutput> pool, ChurnInput input) =>
{
    var result = pool.Predict(input);
    return Results.Ok(new { input.Age, input.Income, input.Region, input.PurchaseHistory,
                            WillChurn = result.PredictedLabel, Probability = result.Probability });
});

app.Run();

namespace ChurnPredictor
{
    public class ChurnInput
    {
        [LoadColumn(0)] public float Age { get; set; }
        [LoadColumn(1)] public float Income { get; set; }
        [LoadColumn(2)] public string Region { get; set; } = "";
        [LoadColumn(3)] public float PurchaseHistory { get; set; }
        [LoadColumn(4)] public string Churned { get; set; } = "";
    }

    public class ChurnOutput
    {
        [ColumnName("PredictedLabel")]
        public bool PredictedLabel { get; set; }
        public float Probability { get; set; }
    }
}

